import type { AgendaEvent } from '@motivation/shared';
import { API_URL } from '../config.js';
import { createJsonClient } from './http.js';

const api = createJsonClient(`${API_URL}/api`);

export class AgendaService {
    static async fetchEvents(): Promise<AgendaEvent[]> {
        return api.get<AgendaEvent[]>('/agenda');
    }
}
