import type { AgendaEvent, CalendarWorkoutRule } from '@motivation/shared';
import stylesText from './agenda-item.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { activityIcon, activityTypeLabel } from '../../../health/health-utils.js';
import { createTrackWorkoutEvent } from '../../agenda-events.js';
import { getAppTimeZone } from '../../../../services/app-timezone.service.js';

const styles = cssStyleSheet(stylesText);

const template = document.createElement('template');
template.innerHTML = `
    <div class="agenda-item">
        <div class="agenda-time">
            <span class="agenda-date" id="date"></span>
            <span class="agenda-hours" id="hours"></span>
        </div>
        <div class="agenda-details" id="details">
            <h3 class="agenda-summary" id="summary"></h3>
        </div>
        <p class="agenda-workout" id="workout" hidden></p>
        <button type="button" class="agenda-track" id="track" hidden>Track as workout</button>
    </div>
`;

export class AgendaItem extends HTMLElement {
    private _event?: AgendaEvent;
    private _rule?: CalendarWorkoutRule | null;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        shadow.getElementById('track')!.addEventListener('click', () => {
            if (this._event) this.dispatchEvent(createTrackWorkoutEvent({ event: this._event }));
        });
    }

    /**
     * Story 402: the workout rule this event matches — null when none does, which offers "Track
     * as workout"; undefined until the rules have loaded, which offers nothing.
     */
    set rule(val: CalendarWorkoutRule | null | undefined) {
        this._rule = val;
        if (this.isConnected) this.update();
    }

    connectedCallback() {
        if (this._event) this.update();
    }

    set event(val: AgendaEvent | undefined) {
        this._event = val;
        if (this.isConnected) {
            this.update();
        }
    }

    get event(): AgendaEvent | undefined {
        return this._event;
    }

    private isDateOnly(dateString: string): boolean {
        return !dateString.includes('T');
    }

    private parseDateTime(dateString: string): Temporal.ZonedDateTime | null {
        if (this.isDateOnly(dateString)) {
            return null;
        }

        // Story 389: the app zone, as health days and reminders use — not the device's.
        return Temporal.Instant.from(dateString).toZonedDateTimeISO(getAppTimeZone());
    }

    private formatTime(dateString: string | undefined | null): string {
        if (!dateString) return '';
        if (this.isDateOnly(dateString)) return 'All day';

        const zdt = this.parseDateTime(dateString);
        if (!zdt) return 'All day';
        return zdt.toLocaleString(undefined, { hour: '2-digit', minute: '2-digit' });
    }

    private formatDate(dateString: string | undefined | null): string {
        if (!dateString) return '';

        if (this.isDateOnly(dateString)) {
            const date = Temporal.PlainDate.from(dateString);
            return date.toLocaleString(undefined, { weekday: 'short', month: 'short', day: 'numeric' });
        }

        const zdt = this.parseDateTime(dateString);
        if (!zdt) return '';
        return zdt.toLocaleString(undefined, { weekday: 'short', month: 'short', day: 'numeric' });
    }

    private update() {
        if (!this._event) return;
        const shadow = this.shadowRoot!;
        const start = this._event.start;
        const end = this._event.end;

        shadow.getElementById('date')!.textContent = this.formatDate(start);
        const isAllDay = start ? this.isDateOnly(start) : false;
        shadow.getElementById('hours')!.textContent = isAllDay
            ? this.formatTime(start)
            : `${this.formatTime(start)} - ${this.formatTime(end)}`;
        shadow.getElementById('summary')!.textContent = this._event.summary ?? '';

        // Handle optional location element
        const details = shadow.getElementById('details')!;
        let locationEl = shadow.getElementById('location');
        if (this._event.location) {
            if (!locationEl) {
                locationEl = document.createElement('p');
                locationEl.id = 'location';
                locationEl.classList.add('agenda-location');
                details.appendChild(locationEl);
            }
            locationEl.textContent = `📍 ${this._event.location}`;
        } else if (locationEl) {
            locationEl.remove();
        }

        const workout = shadow.getElementById('workout')!;
        workout.hidden = !this._rule;
        workout.textContent = this._rule ? `${activityIcon(this._rule.type)} ${activityTypeLabel(this._rule.type)}` : '';
        shadow.getElementById('track')!.hidden = this._rule !== null || !this._event.summary;
    }
}

if (!customElements.get('agenda-item')) {
    customElements.define('agenda-item', AgendaItem);
}
